#!/usr/bin/env python3
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(); p.add_argument("--request",required=True); p.add_argument("--output-dir",required=True); a=p.parse_args(); req=json.loads(Path(a.request).read_text()); result=json.loads(Path(req["agent_result_path"]).read_text()); refs=json.loads(Path(req["reference"]["path"]).read_text()); artifacts=Path(req["artifacts_dir"]); required=refs[req["task_id"]]; ok=bool(result.get("output",{}).get("final_answer")) and all((artifacts/name).is_file() and (artifacts/name).stat().st_size>0 for name in required) and bool(result.get("output",{}).get("execution_logs")); value={"protocol_version":req["protocol_version"],"run_id":req["run_id"],"attempt_id":req["attempt_id"],"task_id":req["task_id"],"status":"scored","metrics":{"task_completed":1.0 if ok else 0.0},"details":{"required_artifacts":required,"present":ok},"evaluator":{"id":"live_analysis_smoke.artifacts","version":"0.1.0"}}; out=Path(a.output_dir); out.mkdir(parents=True,exist_ok=True); (out/"result.json").write_text(json.dumps(value))
